function path(points,fill,stroke=null,width=1){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke()}}
function drawMountain(x,y,w,h,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+w*.28,y-h*.72);ctx.lineTo(x+w*.39,y-h*.49);ctx.lineTo(x+w*.65,y-h);ctx.lineTo(x+w,y);ctx.closePath();ctx.fill();ctx.fillStyle='#f0eee2';ctx.globalAlpha=.48;ctx.beginPath();ctx.moveTo(x+w*.65,y-h);ctx.lineTo(x+w*.54,y-h*.53);ctx.lineTo(x+w*.68,y-h*.61);ctx.lineTo(x+w*.76,y-h*.42);ctx.closePath();ctx.fill();ctx.globalAlpha=1}
function drawBackground(){const world=mode==='world';let sky=ctx.createLinearGradient(0,0,0,H);if(world){sky.addColorStop(0,'#70c7dd');sky.addColorStop(.55,'#c6e7d4');sky.addColorStop(1,'#f4d49b')}else{sky.addColorStop(0,'#19274a');sky.addColorStop(.55,'#443e70');sky.addColorStop(1,'#f39e78')}ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
// sun / moon
const sx=world?930:600,sy=world?190:165;const glow=ctx.createRadialGradient(sx,sy,8,sx,sy,world?115:165);glow.addColorStop(0,world?'#fff5b9aa':'#fff0bb66');glow.addColorStop(1,'#fff3d000');ctx.fillStyle=glow;ctx.fillRect(sx-180,sy-180,360,360);ctx.fillStyle=world?'#fff2b1':'#fff0d6';ctx.globalAlpha=.8;ctx.beginPath();ctx.arc(sx,sy,world?36:55,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
if(world){for(let i=0;i<5;i++){let x=((i*295-worldOffset*.28)%1450+1450)%1450-100;drawMountain(x,430,310,175,['#8bbcae','#81a99f','#9bc6ad'][i%3])}for(let i=0;i<9;i++){let x=((i*190-worldOffset*.48)%1500+1500)%1500-80;ctx.fillStyle=i%2?'#547c68':'#63886d';ctx.beginPath();ctx.moveTo(x,ground+4);ctx.lineTo(x+35,ground-95-(i%3)*15);ctx.lineTo(x+65,ground+4);ctx.fill();ctx.fillStyle='#496954';ctx.fillRect(x+32,ground-7,7,37)}}else{
// arena arc and pillars
ctx.fillStyle='#171d36';ctx.beginPath();ctx.arc(600,384,340,Math.PI,0);ctx.lineTo(940,440);ctx.lineTo(260,440);ctx.closePath();ctx.fill();ctx.strokeStyle='#edc976';ctx.lineWidth=6;ctx.beginPath();ctx.arc(600,384,340,Math.PI,0);ctx.stroke();ctx.lineWidth=2;for(let i=-3;i<=3;i++){let x=600+i*100;ctx.strokeStyle='#efcf8e3b';ctx.beginPath();ctx.moveTo(x,125);ctx.lineTo(x,440);ctx.stroke()}for(let x of [295,905]){ctx.fillStyle='#e7c980';ctx.fillRect(x-13,286,26,164);ctx.fillStyle='#ffdb8d';ctx.fillRect(x-19,280,38,10);ctx.fillStyle='#806252';ctx.fillRect(x-6,305,12,120)}ctx.fillStyle='#f9c671';ctx.globalAlpha=.15;ctx.beginPath();ctx.ellipse(600,445,280,45,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;}
// floating wisps
for(let i=0;i<14;i++){let x=(i*109+frame*.24)%W,y=105+(i*71)%260;ctx.globalAlpha=.13+Math.sin(frame*.02+i)*.06;ctx.fillStyle=world?'#fff':'#c6ceff';ctx.beginPath();ctx.arc(x,y,1.5+(i%3),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
// ground platform
let g=ctx.createLinearGradient(0,ground,0,H);if(world){g.addColorStop(0,'#5e8e62');g.addColorStop(.18,'#776c4b');g.addColorStop(1,'#253c3c')}else{g.addColorStop(0,'#c89e64');g.addColorStop(.13,'#66516c');g.addColorStop(1,'#29243f')}ctx.fillStyle=g;ctx.fillRect(0,ground,W,H-ground);ctx.fillStyle=world?'#c3d291':'#ffce87';ctx.globalAlpha=.82;ctx.fillRect(0,ground,W,5);ctx.globalAlpha=1;
for(let i=0;i<24;i++){let x=((i*74-worldOffset*.9)%W+W)%W;ctx.fillStyle=world?(i%2?'#a0a271':'#59614d'):'#d9a475';ctx.globalAlpha=.32;ctx.fillRect(x,ground+18+(i*29)%110,24+(i%4)*15,1);ctx.globalAlpha=1}if(world){for(let i=0;i<14;i++){let x=((i*103-worldOffset*.7)%W+W)%W;ctx.fillStyle='#f9e59a';ctx.globalAlpha=.8;ctx.fillRect(x,ground-4,2,4);ctx.globalAlpha=1}}
}
function drawFighter(p){if(!p)return;const x=p.x,y=p.y,face=p.face||1,sc=p.scale||1;ctx.save();ctx.translate(x,y);ctx.scale(face*sc,sc);const aura=p.awaken?48:0;if(aura){ctx.globalAlpha=.17+.07*Math.sin(frame*.3);ctx.fillStyle=p.accent;ctx.beginPath();ctx.ellipse(0,-62,aura+10,82+Math.sin(frame*.2)*6,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;for(let i=0;i<4;i++){let ax=Math.sin(frame*.12+i*2)*32,ay=-45-((frame*2+i*37)%95);ctx.fillStyle=p.accent;ctx.globalAlpha=.55;ctx.beginPath();ctx.arc(ax,ay,2+i%2,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
// ground shadow
ctx.fillStyle='#1114225e';ctx.beginPath();ctx.ellipse(0,-1,p.air?25:34,7,0,0,Math.PI*2);ctx.fill();const bob=p.y>=ground-1?Math.sin(p.walk)*2:0;let lift=p.y<ground?-5:0;
// legs
const legSwing=p.y>=ground-1?Math.sin(p.walk)*6:0;ctx.lineCap='round';ctx.lineWidth=13;ctx.strokeStyle='#25314a';ctx.beginPath();ctx.moveTo(-8,-33+bob+lift);ctx.lineTo(-12+legSwing,-9);ctx.stroke();ctx.beginPath();ctx.moveTo(8,-33+bob+lift);ctx.lineTo(12-legSwing,-9);ctx.stroke();ctx.lineWidth=9;ctx.strokeStyle=p.color;ctx.beginPath();ctx.moveTo(-12+legSwing,-10);ctx.lineTo(-17+legSwing,-2);ctx.stroke();ctx.beginPath();ctx.moveTo(12-legSwing,-10);ctx.lineTo(17-legSwing,-2);ctx.stroke();ctx.fillStyle='#ede8df';ctx.fillRect(-24+legSwing,-6,16,6);ctx.fillRect(8-legSwing,-6,16,6);
// torso gi
ctx.fillStyle=p.color;ctx.beginPath();ctx.moveTo(-18,-79+bob+lift);ctx.lineTo(17,-79+bob+lift);ctx.lineTo(20,-35+bob+lift);ctx.lineTo(0,-30+bob+lift);ctx.lineTo(-19,-36+bob+lift);ctx.closePath();ctx.fill();ctx.fillStyle=p.accent;ctx.beginPath();ctx.moveTo(1,-77+bob+lift);ctx.lineTo(13,-74+bob+lift);ctx.lineTo(5,-44+bob+lift);ctx.lineTo(-2,-45+bob+lift);ctx.closePath();ctx.fill();ctx.fillStyle='#25243c';ctx.fillRect(-20,-40+bob+lift,40,7);ctx.fillStyle=p.accent;ctx.fillRect(-4,-40+bob+lift,8,7);
// arms, attack extends forward
let swing=0;if(p.attack>0&&p.attackKind==='punch'){swing=(13-p.attack)*2.8}ctx.lineWidth=12;ctx.lineCap='round';ctx.strokeStyle=p.color;ctx.beginPath();ctx.moveTo(-14,-70+bob+lift);ctx.lineTo(-27,-49+bob+lift);ctx.stroke();ctx.beginPath();ctx.moveTo(14,-70+bob+lift);ctx.lineTo(25+swing,-61+bob+lift);ctx.lineTo(35+swing,-61+bob+lift);ctx.stroke();ctx.fillStyle='#f1c39f';ctx.beginPath();ctx.arc(36+swing,-61+bob+lift,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f1c39f';ctx.beginPath();ctx.arc(-27,-49+bob+lift,6,0,Math.PI*2);ctx.fill();
// head
ctx.fillStyle=p.flash?'#fff':(p.awaken?'#ffe9c2':'#f1c39f');ctx.beginPath();ctx.ellipse(0,-91+bob+lift,16,18,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#202339';ctx.beginPath();ctx.moveTo(-16,-98+bob+lift);ctx.lineTo(-22,-119+bob+lift);ctx.lineTo(-9,-110+bob+lift);ctx.lineTo(-10,-131+bob+lift);ctx.lineTo(1,-116+bob+lift);ctx.lineTo(8,-135+bob+lift);ctx.lineTo(13,-115+bob+lift);ctx.lineTo(25,-124+bob+lift);ctx.lineTo(19,-101+bob+lift);ctx.closePath();ctx.fill();if(p.awaken){ctx.fillStyle=p.accent;ctx.beginPath();ctx.moveTo(-14,-101+bob+lift);ctx.lineTo(-8,-122+bob+lift);ctx.lineTo(-1,-106+bob+lift);ctx.lineTo(7,-126+bob+lift);ctx.lineTo(14,-105+bob+lift);ctx.closePath();ctx.fill()};ctx.fillStyle='#25273a';ctx.fillRect(5,-93+bob+lift,7,2);
if(p.guard){ctx.globalAlpha=.25;ctx.strokeStyle='#b9dbff';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(8,-58,30,44,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}ctx.restore();}
function draw(){ctx.clearRect(0,0,W,H);ctx.save();if(shake>0){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake*=.8}drawBackground();if(mode!=='menu'&&p1){drawFighter(p1);drawFighter(p2)}for(const b of projectiles){ctx.globalAlpha=.3;ctx.fillStyle=b.color;ctx.beginPath();ctx.arc(b.x,b.y,b.r*2.7,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=b.color;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(b.x,b.y,b.r*.55,0,Math.PI*2);ctx.stroke()}for(let i=sparks.length-1;i>=0;i--){let s=sparks[i];ctx.globalAlpha=clamp(s.life/s.max,0,1);ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;s.x+=s.vx;s.y+=s.vy;s.vy+=.12;s.life--;if(s.life<=0)sparks.splice(i,1)}ctx.restore()}
function loop(now){if(mode==='menu'||paused||gameOver)return;let dt=Math.min((now-last)/16.67,2);last=now;frame+=dt;elapsed+=dt/60;roundTimer-=dt/60;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}controlPlayer(p1,controls1);if(mode==='world')cpuUpdate(p2);else controlPlayer(p2,controls2);combat();if(mode==='arena'){ui.round.textContent=Math.max(0,Math.ceil(roundTimer)).toString().padStart(2,'0');if(roundTimer<=0&&!gameOver){resetRound(p1.hp>=p2.hp?p1:p2)}}else{if(Math.abs(p1.x-570)<130&&held('d'))worldOffset+=Math.abs(p1.vx);if(held('a')&&p1.x<150)worldOffset-=Math.abs(p1.vx)}for(let i=0;i<projectiles.length;i++){/* projectile motion is resolved in combat */}updateHud();draw();clearPressed();if(!gameOver)requestAnimationFrame(loop)}
// start button / keyboard convenience
window.addEventListener('keydown',e=>{if(mode==='menu'&&!ui.menu.hidden&&(e.key==='1'||e.key==='2'))startGame(e.key==='1'?'world':'arena')});
// Initial animated title backdrop
function idle(){if(mode==='menu'){frame++;draw();requestAnimationFrame(idle)}}
last=performance.now();idle();
})();
</script>
</body>
